// Worker entry: OpenNext's Next.js handler plus Cron Triggers for the Blizzard sync jobs.
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; SITE_URL?: string } & Record<string, unknown>;
type Ctx = { waitUntil(p: Promise<unknown>): void; passThroughOnException(): void };

// Must match "triggers.crons" in wrangler.jsonc.
const JOBS: Record<string, string> = {
  "*/30 * * * *": "/api/cron/roster",
  "*/10 * * * *": "/api/cron/profiles",
};

export default {
  fetch: handler.fetch,

  async scheduled(event: { cron: string }, env: Env, ctx: Ctx) {
    const path = JOBS[event.cron];
    if (!path || !env.CRON_SECRET) return;
    const url = new URL(path, env.SITE_URL ?? "https://dragonwarriors.app");
    const res: Response = await handler.fetch(new Request(url, { headers: { authorization: `Bearer ${env.CRON_SECRET}` } }), env, ctx);
    console.log(`cron ${event.cron} → ${path}: ${res.status} ${await res.text()}`);
  },
};
